#pragma once
#include "Platform/Vulkan/FVulkanMemoryManager.h"
#include "Platform/Vulkan/VulkanCommandBuffer.h"
#include <set>
#include <thread>
namespace SplatVerification {
inline void RunRound3GPU(Suite& suite,Device& d){
    auto fixture=[&](unsigned count,bool tree=false){
        auto dir=Directory("round3-pool");std::vector<FSplatGaussian> gs(count);
        for(unsigned i=0;i<count;++i){auto& g=gs[i];g.originalId=i;g.position[0]=tree?((i/2)%2?1.f:-1.f)+.01f*(i%2):0;g.position[1]=tree?(i/4?1.f:-1.f):0;g.position[2]=-5;g.scale[0]=g.scale[1]=g.scale[2]=.1f;}
        FSplatLODBuildConfig cfg;cfg.maxLeafGaussians=2;cfg.maxPageGaussians=1;cfg.proxyReduction=.5f;cfg.sourceSHA256=std::string(64,'1');cfg.builderHash=std::string(64,'2');FSplatSceneManifest m;std::string error;FSplatLODBuilder builder;Require(builder.Build(gs,0,cfg,(dir/"scene").string(),m,error),error);return std::make_pair(dir/"scene",m);
    };
    auto pageResult=[&](const auto& f,unsigned id){FSplatPageResult r;r.pageId=id;r.sceneGeneration=1;r.bytes=Read(f.first/f.second.pages[id].relativePath);std::string error;Require(FSplatSceneFormat::DecodePage(f.second,id,r.bytes,r.decodedGaussians,error),error);return r;};
    suite.Test("R2 T09 original source tiny physical budgets reject before any allocation",[&]{
        auto dir=Directory("source-admission");auto ply=dir/"one.ply";std::ofstream file(ply);file<<"ply\nformat ascii 1.0\nelement vertex 1\n";for(auto p:{"x","y","z","f_dc_0","f_dc_1","f_dc_2","opacity","scale_0","scale_1","scale_2","rot_0","rot_1","rot_2","rot_3"})file<<"property float "<<p<<'\n';file<<"end_header\n0 0 -5 .3 .5 .1 1 -2 -2 -2 1 0 0 0\n";file.close();
        auto manager=d.vk->getMemoryManager();FVulkanMemoryManager::FMemoryStats before,after;FSplatPLYLoader loader;FSplatGPUData source;
        for(auto caps:std::vector<std::pair<uint64_t,uint64_t>>{{1,256},{4096,1}}){manager->GetMemoryStats(before);Require(!loader.loadAndUpload(d.rhi,ply.string(),source,caps.first,caps.second)&&!source.isValid(),"infeasible source/staging cap accepted");manager->GetMemoryStats(after);Require(before.TotalAllocated==after.TotalAllocated&&before.TotalReserved==after.TotalReserved&&before.AllocationCount==after.AllocationCount,"budget rejection allocated transient source backing");}
        Require(loader.loadAndUpload(d.rhi,ply.string(),source,4096,256),"bounded original PLY rejected");uint64_t physical=0;
        for(auto buffer:{source.positions,source.scales,source.rotations,source.opacities,source.shCoefficients}){FBufferAllocationInfo allocation;Require(buffer->getAllocationInfo(allocation)&&allocation.reservationBytes==allocation.backingBytes,"source physical backing is not dedicated");physical+=allocation.backingBytes;}
        Require(physical>0&&physical<=4096&&loader.GetStagingBackingBytes()<=256,"independent physical source/staging cap exceeded");auto actual=d.ReadBuffer<float>(source.positions,4);Require(actual[2]==-5&&actual[3]==1,"bounded source upload changed data");
    });
    suite.Test("R1 T06 actual GPU scale and distance clipping match accepted selector controls",[&]{
        float positions[4]={6,0,-5,1},scales[4]={.1f,.1f,.1f,0},rotations[4]={1,0,0,0},opacity=1,sh[3]={.3f,.5f,.1f};FSplatGPUData data;data.gaussianCount=1;data.shDegree=0;
        data.positions=Buffer(d.rhi,16,EMemoryUsage::Upload,positions);data.scales=Buffer(d.rhi,16,EMemoryUsage::Upload,scales);data.rotations=Buffer(d.rhi,16,EMemoryUsage::Upload,rotations);data.opacities=Buffer(d.rhi,4,EMemoryUsage::Upload,&opacity);data.shCoefficients=Buffer(d.rhi,12,EMemoryUsage::Upload,sh);
        FSplatPipeline pipeline;pipeline.SetCapacityBudgets(1,1,256,16ull<<20);Require(pipeline.initialize(d.rhi,1,64,64),"controls pipeline initialization");pipeline.setGaussianData(data);pipeline.setCamera(Camera(0));
        auto count=[&](float scale,bool clipping,float farPlane){FSplatRenderSettings settings;settings.gaussianScale=scale;settings.distanceCulling=clipping;settings.farPlane=farPlane;pipeline.setRenderSettings(settings);auto command=d.Begin();Require(bool(pipeline.execute(command)),"controls actual dispatch");auto token=d.Submit(command);pipeline.MarkFrameSubmitted(token);return d.ReadBuffer<unsigned>(pipeline.GetDispatchStateBuffer(),5)[0];};
        Require(count(1,true,1000)==0&&count(10,true,1000)>0,"scaled support did not create actual visible GPU tiles");positions[0]=0;auto mapped=data.positions->map();Require(mapped!=nullptr,"position update map");std::memcpy(mapped,positions,16);data.positions->unmap();Require(count(1,true,4)==0&&count(1,false,4)>0,"disabled distance clipping not honored on GPU");
    });
    suite.Test("R5 T09 mixed pooled dedicated allocation retains honest pooled slack",[&]{
        auto manager=d.vk->getMemoryManager();BufferDesc sharedDesc;sharedDesc.size=4096;sharedDesc.usage=EResourceUsage::StorageBuffer;auto shared=d.rhi->createBuffer(sharedDesc);Require(bool(shared),"mixed shared allocation");FVulkanMemoryManager::FMemoryStats before,after;manager->GetMemoryStats(before);
        BufferDesc dedicatedDesc=sharedDesc;dedicatedDesc.size=64u<<20;dedicatedDesc.dedicatedAllocation=true;auto dedicated=d.rhi->createBuffer(dedicatedDesc);Require(bool(dedicated),"mixed dedicated allocation");manager->GetMemoryStats(after);uint64 used=0,available=0;d.rhi->getMemoryStats(used,available);
        Require(after.DedicatedCommitted>before.DedicatedCommitted&&after.PooledReserved==before.PooledReserved&&after.PooledUsed==before.PooledUsed,"dedicated backing polluted pooled counters");Require(available>0&&available==after.PooledReserved-after.PooledUsed,"dedicated backing erased free shared capacity");Require(after.TotalReserved==after.PooledReserved+after.DedicatedCommitted&&used==after.PooledUsed+after.DedicatedCommitted,"allocator committed and used categories disagree");
    });
    suite.Test("R4 T08 T09 GPU pending dedup avoids reread after payload destruction",[&]{
        auto f=fixture(1);FSplatStreamingConfig cfg;cfg.sceneGPUBytes=4096;cfg.stagingBytes=256;cfg.maxUploadBytesPerFrame=256;cfg.cpuCacheBytes=65536;FSplatPageStreamer streamer;FSplatGPUPagePool pool;std::string error;Require(streamer.Open(f.second,f.first.string(),cfg,error)&&pool.Initialize(d.rhi,f.second,cfg,error),error);
        bool completed=false;pool.SetCompletionGate([&](FGPUCompletionToken){return completed;});streamer.UpdateRequests({{0,1,1}});std::vector<FSplatPageResult> results;auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(3);while(results.empty()&&std::chrono::steady_clock::now()<deadline){results=streamer.DrainReady();std::this_thread::sleep_for(std::chrono::milliseconds(1));}Require(results.size()==1,"streamer result deadline");Require(pool.TryQueueUpload(std::move(results[0]),error),error);results.clear();auto command=d.Begin();pool.Tick(command,1);auto token=d.Submit(command);pool.MarkFrameSubmitted(token);for(auto lease:pool.DrainReleasedTransfers())Require(streamer.ReleaseTransferred(lease.first,lease.second),"destroyed payload lease release");
        Require(pool.GetPendingCPUBytes()==0&&streamer.GetMemoryStats().transferredBytes==0&&pool.HasPage(0,1)&&!pool.GetResidency().IsPageReady(0)&&!pool.HasPage(0,2),"GPU pending identity lost when CPU storage destroyed");
        auto disk=streamer.GetStats().bytesRead;for(unsigned frame=0;frame<20;++frame){std::vector<FSplatPageRequest> wanted;if(!pool.HasPage(0,1))wanted.push_back({0,1,1});streamer.UpdateRequests(wanted);command=d.Begin();pool.Tick(command,1);token=d.Submit(command);pool.MarkFrameSubmitted(token);Require(streamer.DrainReady().empty(),"already uploading page reread");}
        Require(streamer.GetStats().bytesRead==disk&&disk==f.second.pages[0].byteSize&&pool.GetStats().rejectedUploads==0,"uploading dedup caused redundant I/O/admission");completed=true;command=d.Begin();pool.Tick(command,1);d.Submit(command);Require(pool.GetResidency().IsPageReady(0)&&pool.HasPage(0,1),"real completed upload did not become ready");pool.Shutdown();streamer.Shutdown();Require(streamer.GetMemoryStats().totalReservedBytes==0,"pending dedup CPU accounting leak");
    });
    suite.Test("R4 T09 obsolete unallocated pool payload closes its genuine consumer lease",[&]{
        auto f=fixture(8,true);auto id=f.second.nodes[f.second.nodes[0].children[0]].pageIds[0];FSplatStreamingConfig cfg;cfg.sceneGPUBytes=4096;cfg.stagingBytes=1024;cfg.maxUploadBytesPerFrame=1024;cfg.cpuCacheBytes=65536;FSplatPageStreamer streamer;FSplatGPUPagePool pool;std::string error;Require(streamer.Open(f.second,f.first.string(),cfg,error)&&pool.Initialize(d.rhi,f.second,cfg,error),error);streamer.UpdateRequests({{id,1,1}});std::vector<FSplatPageResult> results;auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(3);while(results.empty()&&std::chrono::steady_clock::now()<deadline){results=streamer.DrainReady();std::this_thread::sleep_for(std::chrono::milliseconds(1));}Require(results.size()==1&&pool.TryQueueUpload(std::move(results[0]),error),error);results.clear();auto charge=streamer.GetMemoryStats().transferredBytes;Require(charge>0&&pool.HasPage(id,1)&&pool.GetPendingCPUBytes()>0,"queued obsolete payload fixture missing");FSplatLODSelection rootOnly;rootOnly.selectedNodeIds={0};pool.ProtectSelection(rootOnly);Require(!pool.HasPage(id,1)&&pool.GetPendingCPUBytes()==0&&streamer.GetMemoryStats().transferredBytes==charge,"pool cancellation lost lease or retained obsolete payload");auto leases=pool.DrainReleasedTransfers();Require(leases==std::vector<std::pair<uint32_t,uint64_t>>{{id,1}},"obsolete pool result release identity missing");Require(streamer.ReleaseTransferred(id,1),"destroyed obsolete consumer release rejected");streamer.UpdateRequests({});pool.Shutdown();streamer.Shutdown();Require(streamer.GetMemoryStats().totalReservedBytes==0,"obsolete pool consumer accounting failed shutdown");
    });
    suite.Test("R6 T09 real incomplete multipage use prevents eviction then reuses new generations",[&]{
        auto f=fixture(8,true);auto& m=f.second;Require(m.nodes.size()==5&&m.nodes[0].children.size()==4&&m.nodes[0].pageIds.size()==4,"multipage sparse fixture shape");for(auto node:m.nodes[0].children)Require(m.nodes[node].pageIds.size()==2,"each leaf must span two pages");
        const auto victim=m.nodes[0].children[0],current=m.nodes[0].children[1],transition=m.nodes[0].children[2],replacement=m.nodes[0].children[3];
        auto required=[&](unsigned count){uint64_t total=0;for(unsigned width:{16u,16u,16u,4u,12u}){BufferDesc desc;desc.size=count*width;desc.usage=EResourceUsage::StorageBuffer|EResourceUsage::TransferDst;desc.dedicatedAllocation=true;uint64 bytes=0,alignment=0;Require(d.rhi->getBufferAllocationRequirements(desc,bytes,alignment),"exact fixture allocation requirements");total+=bytes;}return total;};
        FSplatStreamingConfig cfg;cfg.sceneGPUBytes=required(10);cfg.stagingBytes=1024;cfg.maxUploadBytesPerFrame=1024;cfg.cpuCacheBytes=65536;FSplatGPUPagePool pool;std::string error;Require(pool.Initialize(d.rhi,m,cfg,error),error);Require(pool.GetGPUData().gaussianCount==10,"physical fixture does not constrain source to ten slots");auto allocation=pool.GetAllocationStats();
        FSplatLODSelection initial;for(auto node:{0u,victim,current,transition})for(auto page:m.nodes[node].pageIds)initial.requestPageIds.push_back(page);pool.ProtectSelection(initial);
        for(auto page:initial.requestPageIds)Require(pool.TryQueueUpload(pageResult(f,page),error),error);auto command=d.Begin();pool.Tick(command,1);auto upload=d.Submit(command);pool.MarkFrameSubmitted(upload);command=d.Begin();pool.Tick(command,1);d.Submit(command);auto before=pool.GetResidency();Require(before.IsNodeReady(m,0)&&before.IsNodeReady(m,victim)&&before.IsNodeReady(m,current)&&before.IsNodeReady(m,transition),"initial full physical pool not ready");pool.DrainReleasedTransfers();
        FSplatLODSelection active;active.selectedNodeIds={victim};active.selectionVersion=1;auto indices=pool.BuildActiveSet(active);Require(indices.sourceIndices.size()==2,"victim actual active mapping");
        FSplatPipeline pipeline;pipeline.SetCapacityBudgets(10,2,256,16ull<<20);Require(pipeline.initialize(d.rhi,10,64,64),"inflight-use pipeline");pipeline.setGaussianData(pool.GetGPUData());pipeline.setCamera(Camera(0));pipeline.SetActiveSet(indices);
        struct EventGuard{VkDevice device;VkEvent event=VK_NULL_HANDLE;~EventGuard(){if(event){vkSetEvent(device,event);vkDeviceWaitIdle(device);vkDestroyEvent(device,event,nullptr);}}} blocker{d.vk->getLogicalDevice()};VkEventCreateInfo create{VK_STRUCTURE_TYPE_EVENT_CREATE_INFO};Require(vkCreateEvent(blocker.device,&create,nullptr,&blocker.event)==VK_SUCCESS,"actual host event creation");
        command=d.Begin();auto context=d.vk->getCommandListContext();vkCmdWaitEvents(context->getCmdBuffer()->getHandle(),1,&blocker.event,VK_PIPELINE_STAGE_HOST_BIT,VK_PIPELINE_STAGE_ALL_COMMANDS_BIT,0,nullptr,0,nullptr,0,nullptr);Require(bool(pipeline.execute(command)),"actual source use recording");command->end();auto manager=context->getCommandBufferManager();Require(manager->submitActiveCmdBuffer(nullptr,0,nullptr,0),"real nonblocking use submission");auto use=d.rhi->getLastSubmissionToken();Require(use.value&&use.value!=upload.value&&!d.rhi->isSubmissionComplete(use),"unsignaled event did not hold actual submitted use incomplete");pool.MarkFrameSubmitted(use);pipeline.MarkFrameSubmitted(use);
        FSplatLODSelection protectedCut;protectedCut.selectedNodeIds={current};for(auto node:{transition,replacement})for(auto page:m.nodes[node].pageIds)protectedCut.requestPageIds.push_back(page);pool.ProtectSelection(protectedCut);for(auto page:m.nodes[replacement].pageIds)Require(pool.TryQueueUpload(pageResult(f,page),error),error);
        pool.SetCompletionGate([](FGPUCompletionToken){return true;});command=d.Begin();pool.Tick(command,1);command->end();auto blocked=pool.GetResidency();Require(pool.GetStats().evictedPages==0&&pool.GetStats().inFlightPages>=2&&pool.GetStats().pendingUploads==2,"incomplete use was reclaimed or replacement discarded");
        for(auto node:{0u,victim,current,transition})for(auto page:m.nodes[node].pageIds)Require(blocked.pages[page].ready&&blocked.pages[page].sourceOffset==before.pages[page].sourceOffset&&blocked.pages[page].generation==before.pages[page].generation,"incomplete use/protected root/current/transition mapping changed");
        Require(!blocked.IsNodeReady(m,replacement),"replacement prematurely ready");Require(vkSetEvent(blocker.device,blocker.event)==VK_SUCCESS,"real submission release");d.rhi->waitForIdle();Require(d.rhi->isSubmissionComplete(use),"released real submission remained incomplete");pool.SetCompletionGate([&](FGPUCompletionToken token){return token.value!=use.value;});command=d.Begin();pool.Tick(command,1);command->end();Require(pool.GetStats().evictedPages==0,"completion delay seam failed to retain submitted use");
        pool.SetCompletionGate({});command=d.Begin();pool.Tick(command,1);auto recorded=pool.GetResidency();Require(pool.GetStats().evictedPages==2&&!recorded.IsNodeReady(m,victim)&&!recorded.IsNodeReady(m,replacement),"legal reclamation not exactly two pages or published unsubmitted upload");Require(pool.BuildActiveSet(active).sourceIndices.empty(),"stale victim selection retained reused slots");
        std::set<unsigned> oldOffsets,newOffsets;uint64_t oldGeneration=0;for(auto page:m.nodes[victim].pageIds){oldOffsets.insert(before.pages[page].sourceOffset);oldGeneration=std::max(oldGeneration,before.pages[page].generation);}for(auto page:m.nodes[replacement].pageIds){newOffsets.insert(recorded.pages[page].sourceOffset);Require(recorded.pages[page].generation>oldGeneration,"reused slot generation did not advance");}Require(oldOffsets==newOffsets,"replacement did not genuinely reuse victim slots");
        auto replaceToken=d.Submit(command);pool.MarkFrameSubmitted(replaceToken);command=d.Begin();pool.Tick(command,1);d.Submit(command);auto after=pool.GetResidency();Require(after.IsNodeReady(m,replacement)&&after.IsNodeReady(m,current)&&after.IsNodeReady(m,transition)&&after.IsNodeReady(m,0),"legal replacement broke protected ready coverage");auto finalAllocation=pool.GetAllocationStats();Require(finalAllocation.sourceBackingBytes==allocation.sourceBackingBytes&&finalAllocation.sourceBackingBytes<=cfg.sceneGPUBytes,"reclamation grew physical source backing");pool.DrainReleasedTransfers();pool.Shutdown();
    });
}
}
